package dev.yinghuang.legacyforgebridge.convert;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.objectweb.asm.AnnotationVisitor;
import org.objectweb.asm.ClassWriter;
import org.objectweb.asm.Label;
import org.objectweb.asm.MethodVisitor;
import org.objectweb.asm.Opcodes;
import org.objectweb.asm.Type;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.jar.JarEntry;
import java.util.jar.JarOutputStream;

import static org.junit.jupiter.api.Assertions.*;

class LegacyOscillatingModelBlockAnalyzerTest {
    @TempDir Path tempDir;
    @Test void unrelatedClientOnlyOscillatorIsAdmittedWhileNbtStateIsRejected()throws Exception{
        Path jar=tempDir.resolve("oscillator.jar");try(JarOutputStream out=new JarOutputStream(Files.newOutputStream(jar))){
            put(out,"foreign/osc/Block.class",block("foreign/osc/Block","foreign/osc/Tile",new int[]{3,0,2,1}));put(out,"foreign/osc/Tile.class",tile("foreign/osc/Tile",false));
            put(out,"foreign/osc/PersistentBlock.class",block("foreign/osc/PersistentBlock","foreign/osc/PersistentTile",new int[]{0,1,2,3}));put(out,"foreign/osc/PersistentTile.class",tile("foreign/osc/PersistentTile",true));put(out,"foreign/osc/Bootstrap.class",bootstrap());
        }
        var analysis=new LegacyOscillatingModelBlockAnalyzer().analyze(jar);assertTrue(analysis.diagnostics().isEmpty(),analysis.diagnostics().toString());assertEquals(1,analysis.rules().size());var rule=analysis.rules().getFirst();assertEquals("oscillator",rule.registryName());assertEquals("foreign/osc/Tile",rule.sourceTileClass());assertEquals("osc_tile",rule.legacyTileId());assertArrayEquals(new int[]{3,0,2,1},rule.placementMetaByYawQuadrant());assertTrue(rule.fullCube());assertEquals(0,rule.lightEmission());assertTrue(rule.clientOnly());assertFalse(rule.nbtPersistent());assertEquals(80,rule.randomInitialBound());assertEquals(.25F,rule.stepDegrees());assertEquals(0F,rule.lowerBoundDegrees());assertEquals(30F,rule.upperBoundDegrees());assertTrue(analysis.skipped().stream().anyMatch(s->s.sourceBlockClass().equals("foreign/osc/PersistentBlock")));
    }
    private static byte[] bootstrap(){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,"foreign/osc/Bootstrap",null,"java/lang/Object",null);MethodVisitor m=w.visitMethod(Opcodes.ACC_PUBLIC,"preInit","(Lcpw/mods/fml/common/event/FMLPreInitializationEvent;)V",null,null);AnnotationVisitor event=m.visitAnnotation("Lcpw/mods/fml/common/Mod$EventHandler;",true);event.visitEnd();m.visitCode();register(m,"foreign/osc/Block","oscillator","foreign/osc/Tile","osc_tile");register(m,"foreign/osc/PersistentBlock","persistent","foreign/osc/PersistentTile","persistent_tile");m.visitInsn(Opcodes.RETURN);m.visitMaxs(0,0);m.visitEnd();w.visitEnd();return w.toByteArray();}
    private static void register(MethodVisitor m,String block,String id,String tile,String tileId){m.visitTypeInsn(Opcodes.NEW,block);m.visitInsn(Opcodes.DUP);m.visitMethodInsn(Opcodes.INVOKESPECIAL,block,"<init>","()V",false);m.visitLdcInsn(id);m.visitMethodInsn(Opcodes.INVOKESTATIC,"cpw/mods/fml/common/registry/GameRegistry","registerBlock","(Lnet/minecraft/block/Block;Ljava/lang/String;)V",false);m.visitLdcInsn(Type.getObjectType(tile));m.visitLdcInsn(tileId);m.visitMethodInsn(Opcodes.INVOKESTATIC,"cpw/mods/fml/common/registry/GameRegistry","registerTileEntity","(Ljava/lang/Class;Ljava/lang/String;)V",false);}
    private static byte[] block(String name,String tile,int[] mapping){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,name,null,"net/minecraft/block/BlockContainer",null);MethodVisitor c=w.visitMethod(Opcodes.ACC_PUBLIC,"<init>","()V",null,null);c.visitCode();c.visitVarInsn(Opcodes.ALOAD,0);c.visitInsn(Opcodes.ACONST_NULL);c.visitMethodInsn(Opcodes.INVOKESPECIAL,"net/minecraft/block/BlockContainer","<init>","(Lnet/minecraft/block/material/Material;)V",false);c.visitInsn(Opcodes.RETURN);c.visitMaxs(0,0);c.visitEnd();bool(w,"func_149662_c",false);bool(w,"func_149686_d",false);intReturn(w,"func_149656_h",1);MethodVisitor create=w.visitMethod(Opcodes.ACC_PUBLIC,"func_149915_a","(Lnet/minecraft/world/World;I)Lnet/minecraft/tileentity/TileEntity;",null,null);create.visitCode();create.visitTypeInsn(Opcodes.NEW,tile);create.visitInsn(Opcodes.DUP);create.visitMethodInsn(Opcodes.INVOKESPECIAL,tile,"<init>","()V",false);create.visitInsn(Opcodes.ARETURN);create.visitMaxs(0,0);create.visitEnd();MethodVisitor p=w.visitMethod(Opcodes.ACC_PUBLIC,"func_149689_a","(Lnet/minecraft/world/World;IIILnet/minecraft/entity/EntityLivingBase;Lnet/minecraft/item/ItemStack;)V",null,null);p.visitCode();p.visitInsn(Opcodes.ICONST_0);p.visitVarInsn(Opcodes.ISTORE,7);p.visitVarInsn(Opcodes.ALOAD,5);p.visitFieldInsn(Opcodes.GETFIELD,"net/minecraft/entity/EntityLivingBase","field_70177_z","F");p.visitLdcInsn(4F);p.visitInsn(Opcodes.FMUL);p.visitLdcInsn(360F);p.visitInsn(Opcodes.FDIV);p.visitInsn(Opcodes.F2D);p.visitLdcInsn(.5D);p.visitInsn(Opcodes.DADD);p.visitMethodInsn(Opcodes.INVOKESTATIC,"net/minecraft/util/MathHelper","func_76128_c","(D)I",false);p.visitInsn(Opcodes.ICONST_3);p.visitInsn(Opcodes.IAND);Label[] labels={new Label(),new Label(),new Label(),new Label()};Label end=new Label();p.visitTableSwitchInsn(0,3,end,labels);for(int i=0;i<4;i++){p.visitLabel(labels[i]);pushInt(p,mapping[i]);p.visitVarInsn(Opcodes.ISTORE,7);p.visitJumpInsn(Opcodes.GOTO,end);}p.visitLabel(end);p.visitVarInsn(Opcodes.ALOAD,1);p.visitVarInsn(Opcodes.ILOAD,2);p.visitVarInsn(Opcodes.ILOAD,3);p.visitVarInsn(Opcodes.ILOAD,4);p.visitVarInsn(Opcodes.ILOAD,7);p.visitInsn(Opcodes.ICONST_3);p.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"net/minecraft/world/World","func_72921_c","(IIIII)Z",false);p.visitInsn(Opcodes.POP);p.visitInsn(Opcodes.RETURN);p.visitMaxs(0,0);p.visitEnd();w.visitEnd();return w.toByteArray();}
    private static byte[] tile(String name,boolean nbt){ClassWriter w=new ClassWriter(ClassWriter.COMPUTE_MAXS);w.visit(Opcodes.V1_7,Opcodes.ACC_PUBLIC,name,null,"net/minecraft/tileentity/TileEntity",null);w.visitField(Opcodes.ACC_PRIVATE,"swing","F",null,null).visitEnd();w.visitField(Opcodes.ACC_PRIVATE,"direction","Z",null,null).visitEnd();w.visitField(Opcodes.ACC_PRIVATE|Opcodes.ACC_STATIC|Opcodes.ACC_FINAL,"RAND","Ljava/util/Random;",null,null).visitEnd();MethodVisitor c=w.visitMethod(Opcodes.ACC_PUBLIC,"<init>","()V",null,null);c.visitCode();c.visitVarInsn(Opcodes.ALOAD,0);c.visitMethodInsn(Opcodes.INVOKESPECIAL,"net/minecraft/tileentity/TileEntity","<init>","()V",false);c.visitVarInsn(Opcodes.ALOAD,0);c.visitFieldInsn(Opcodes.GETSTATIC,name,"RAND","Ljava/util/Random;");c.visitIntInsn(Opcodes.BIPUSH,80);c.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"java/util/Random","nextInt","(I)I",false);c.visitInsn(Opcodes.I2F);c.visitFieldInsn(Opcodes.PUTFIELD,name,"swing","F");c.visitVarInsn(Opcodes.ALOAD,0);c.visitFieldInsn(Opcodes.GETSTATIC,name,"RAND","Ljava/util/Random;");c.visitMethodInsn(Opcodes.INVOKEVIRTUAL,"java/util/Random","nextBoolean","()Z",false);c.visitFieldInsn(Opcodes.PUTFIELD,name,"direction","Z");c.visitInsn(Opcodes.RETURN);c.visitMaxs(0,0);c.visitEnd();MethodVisitor tick=w.visitMethod(Opcodes.ACC_PUBLIC,"func_145845_h","()V",null,null);tick.visitCode();Label dec=new Label(),end=new Label(),toggleUp=new Label(),toggleDown=new Label();tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitFieldInsn(Opcodes.GETFIELD,name,"field_145850_b","Lnet/minecraft/world/World;");tick.visitFieldInsn(Opcodes.GETFIELD,"net/minecraft/world/World","field_72995_K","Z");tick.visitJumpInsn(Opcodes.IFEQ,end);tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitFieldInsn(Opcodes.GETFIELD,name,"direction","Z");tick.visitJumpInsn(Opcodes.IFEQ,dec);tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitInsn(Opcodes.DUP);tick.visitFieldInsn(Opcodes.GETFIELD,name,"swing","F");tick.visitInsn(Opcodes.F2D);tick.visitLdcInsn(.25D);tick.visitInsn(Opcodes.DADD);tick.visitInsn(Opcodes.D2F);tick.visitInsn(Opcodes.DUP_X1);tick.visitFieldInsn(Opcodes.PUTFIELD,name,"swing","F");tick.visitLdcInsn(30F);tick.visitInsn(Opcodes.FCMPG);tick.visitJumpInsn(Opcodes.IFLT,end);toggle(tick,name,"direction",toggleUp);tick.visitJumpInsn(Opcodes.GOTO,end);tick.visitLabel(dec);tick.visitVarInsn(Opcodes.ALOAD,0);tick.visitInsn(Opcodes.DUP);tick.visitFieldInsn(Opcodes.GETFIELD,name,"swing","F");tick.visitInsn(Opcodes.F2D);tick.visitLdcInsn(.25D);tick.visitInsn(Opcodes.DSUB);tick.visitInsn(Opcodes.D2F);tick.visitInsn(Opcodes.DUP_X1);tick.visitFieldInsn(Opcodes.PUTFIELD,name,"swing","F");tick.visitInsn(Opcodes.FCONST_0);tick.visitInsn(Opcodes.FCMPL);tick.visitJumpInsn(Opcodes.IFGT,end);toggle(tick,name,"direction",toggleDown);tick.visitLabel(end);tick.visitInsn(Opcodes.RETURN);tick.visitMaxs(0,0);tick.visitEnd();if(nbt){MethodVisitor read=w.visitMethod(Opcodes.ACC_PUBLIC,"func_145839_a","(Lnet/minecraft/nbt/NBTTagCompound;)V",null,null);read.visitCode();read.visitInsn(Opcodes.RETURN);read.visitMaxs(0,0);read.visitEnd();}MethodVisitor s=w.visitMethod(Opcodes.ACC_STATIC,"<clinit>","()V",null,null);s.visitCode();s.visitTypeInsn(Opcodes.NEW,"java/util/Random");s.visitInsn(Opcodes.DUP);s.visitMethodInsn(Opcodes.INVOKESPECIAL,"java/util/Random","<init>","()V",false);s.visitFieldInsn(Opcodes.PUTSTATIC,name,"RAND","Ljava/util/Random;");s.visitInsn(Opcodes.RETURN);s.visitMaxs(0,0);s.visitEnd();w.visitEnd();return w.toByteArray();}
    private static void toggle(MethodVisitor m,String owner,String field,Label falseLabel){Label after=new Label();m.visitVarInsn(Opcodes.ALOAD,0);m.visitVarInsn(Opcodes.ALOAD,0);m.visitFieldInsn(Opcodes.GETFIELD,owner,field,"Z");m.visitJumpInsn(Opcodes.IFNE,falseLabel);m.visitInsn(Opcodes.ICONST_1);m.visitJumpInsn(Opcodes.GOTO,after);m.visitLabel(falseLabel);m.visitInsn(Opcodes.ICONST_0);m.visitLabel(after);m.visitFieldInsn(Opcodes.PUTFIELD,owner,field,"Z");}
    private static void bool(ClassWriter w,String name,boolean value){MethodVisitor m=w.visitMethod(Opcodes.ACC_PUBLIC,name,"()Z",null,null);m.visitCode();m.visitInsn(value?Opcodes.ICONST_1:Opcodes.ICONST_0);m.visitInsn(Opcodes.IRETURN);m.visitMaxs(0,0);m.visitEnd();}private static void intReturn(ClassWriter w,String name,int value){MethodVisitor m=w.visitMethod(Opcodes.ACC_PUBLIC,name,"()I",null,null);m.visitCode();pushInt(m,value);m.visitInsn(Opcodes.IRETURN);m.visitMaxs(0,0);m.visitEnd();}private static void pushInt(MethodVisitor m,int value){if(value>=0&&value<=5)m.visitInsn(Opcodes.ICONST_0+value);else m.visitIntInsn(Opcodes.BIPUSH,value);}private static void put(JarOutputStream out,String name,byte[] bytes)throws Exception{out.putNextEntry(new JarEntry(name));out.write(bytes);out.closeEntry();}
}
